grammar inference.fragments.TypedBasic hidden(WS)
generate fragments "urn:inference:fragments:typed_basic"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: Fields;
fragment Fields: name=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.WildcardBasic hidden(WS)
generate fragments "urn:inference:fragments:wildcard_basic"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: 'm' Fields;
fragment Fields*: name=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.WildcardTypedCall hidden(WS)
generate fragments "urn:inference:fragments:wildcard_typed_call"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: Fields;
fragment Fields*: Common;
fragment Common: name=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.WildcardOverride.Parent hidden(WS)
generate parent "urn:inference:fragments:wildcard_override:parent"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Root: 'r' Fields;
fragment Fields*: name=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.WildcardOverride.Child with inference.fragments.WildcardOverride.Parent
generate child "urn:inference:fragments:wildcard_override:child"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: Fields;
fragment Fields*: name=ID ('tag' tag=ID)?;

grammar inference.fragments.wildcardoverride.Parent hidden(WS)
generate parent "urn:inference:fragments:wildcard_override:parent"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Root: 'r' Fields;
fragment Fields*: name=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.wildcardoverride.Child with inference.fragments.wildcardoverride.Parent
generate child "urn:inference:fragments:wildcard_override:child"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: Fields;
fragment Fields*: name=ID ('tag' tag=ID)?;

grammar inference.fragments.wildcardoverride.Parent hidden(WS)
generate parent "urn:inference:fragments:wildcard_override:parent"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Root: 'r' Fields;
fragment Fields*: name=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.wildcardoverride.Reachable with inference.fragments.wildcardoverride.Parent
generate child "urn:inference:fragments:wildcard_override:child"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Holder: node=Root;
fragment Fields*: name=ID ('tag' tag=ID)?;

grammar inference.fragments.runtime.Compatible hidden(WS)
generate runtime "urn:inference:fragment-runtime:wildcard_typed_compatible"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: 'm' name=ID Fields;
fragment Fields*: Common;
fragment Common: name=ID;
terminal ID: ('a'..'z')+;
terminal INT returns ecore::EInt: ('0'..'9')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.runtime.Incompatible hidden(WS)
generate runtime "urn:inference:fragment-runtime:wildcard_typed_incompatible"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: 'm' name=INT Fields;
fragment Fields*: Common;
fragment Common: name=ID;
terminal ID: ('a'..'z')+;
terminal INT returns ecore::EInt: ('0'..'9')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.runtime.UnusedAssigned hidden(WS)
generate runtime "urn:inference:fragment-runtime:unused_assigned_fragment"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: name=ID;
fragment Fields*: bad=Common;
fragment Common: name=ID;
terminal ID: ('a'..'z')+;
terminal INT returns ecore::EInt: ('0'..'9')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.runtime.NumericString hidden(WS)
generate runtime "urn:inference:fragment-runtime:wildcard_numeric_string"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: {Root} Fields;
Other returns Root: number=Count;
fragment Fields*: Generic;
fragment Generic: number=WORD;
terminal Count returns ecore::EInt: 'i' ('0'..'9')+;
terminal WORD: ('0'..'9')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;
